INSERT INTO public.pool_scores (hotel_id, pool_score_0_10, best_time, pool_type, editorial_notes) VALUES
((SELECT id FROM public.hotels WHERE slug='elounda-mare-relais-chateaux'), 9.5, 'May–October', 'Private bungalow pools · seawater main pool', 'Bungalows with their own heated seawater pools stepped down toward the bay, plus a large seawater main pool framed by bougainvillea.'),
((SELECT id FROM public.hotels WHERE slug='blue-palace-a-luxury-collection-resort'), 9.4, 'May–October', 'Infinity pool · private villa pools', 'A terraced hillside of private pools ending in an infinity deck that looks straight across the water to Spinalonga island.'),
((SELECT id FROM public.hotels WHERE slug='domes-zeen-chania-a-luxury-collection-resort'), 9.2, 'May–October', 'Lagoon-style main pool · private pools', 'A low-slung, garden-heavy resort where the main pool curves through palms a few steps from the sand.'),
((SELECT id FROM public.hotels WHERE slug='nana-princess-suites-villas-spa'), 9.1, 'April–October', 'Private heated pools · beachfront pools', 'An adults-oriented beachfront resort built around private heated pools, with sea-facing decks and an oversized spa.'),
((SELECT id FROM public.hotels WHERE slug='daios-cove-luxury-resort-villas'), 9, 'May–October', 'Cliffside main pool · private villa pools', 'Villas cascade down a cliff into a private cove, each with its own pool, above a large sea-level main pool and beach club.'),
((SELECT id FROM public.hotels WHERE slug='amirandes-grecotel-boutique-resort'), 8.9, 'May–October', 'Lagoon pool · Olympic-length pool', 'A saltwater lagoon pool weaves between villas and gardens, alongside a serious lap pool right by the beach.'),
((SELECT id FROM public.hotels WHERE slug='abaton-island-resort-spa'), 8.8, 'May–October', 'Infinity pools · private suite pools', 'Stacked infinity decks and dozens of private pools on a rocky headland, with a design-forward adults area.'),
((SELECT id FROM public.hotels WHERE slug='casa-delfino-hotel-spa'), 8.6, 'May–October', 'Rooftop plunge pool · old town view', 'A 17th-century mansion in the old town with a small rooftop plunge pool looking over tiled roofs to the harbour and the White Mountains.'),
((SELECT id FROM public.hotels WHERE slug='cayo-exclusive-resort-spa'), 8.6, 'May–October', 'Infinity pool · private pools', 'A small hillside resort in Plaka where the infinity pool and private suite pools all aim at Spinalonga.'),
((SELECT id FROM public.hotels WHERE slug='kalimera-kriti-hotel-village-resort'), 8.4, 'April–October', 'Multiple outdoor pools · heated indoor pool', 'A sprawling low-rise resort with a series of connected outdoor pools plus a heated indoor pool for shoulder season.'),
((SELECT id FROM public.hotels WHERE slug='minos-beach-art-hotel'), 8.3, 'May–October', 'Seafront pool · private bungalow pools', 'Bungalows scattered through an art-filled seafront garden, with a calm main pool and several private pools by the rocks.'),
((SELECT id FROM public.hotels WHERE slug='stella-island-luxury-resort-spa'), 8.2, 'May–October', 'Swim-up suites · lagoon pool network', 'An adults-only resort built around a lagoon pool network — most suites open directly onto the water.'),
((SELECT id FROM public.hotels WHERE slug='avra-imperial-hotel'), 8.1, 'April–October', 'Large outdoor pools · heated indoor pool', 'Huge freeform pools set in gardens near Kolymbari beach, plus an indoor heated pool and spa for cooler months.'),
